Method.Implementation:
Set tStatus = $$$OK
Try {
	If $IsObject(..BGN) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollBGN).PutObject(pIOStream,..BGN,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..REF1) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollREF1).PutObject(pIOStream,..REF1,0)
		If $$$ISERR(tStatus) Quit
	}
	For i=1:1:..N1.Count() {
		Set tElement = ..N1.GetAt(i)
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollN1).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..N1.%UnSwizzleAt(i)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(..INS) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollINS).PutObject(pIOStream,..INS,0)
		If $$$ISERR(tStatus) Quit
	}
	For i=1:1:..REF2.Count() {
		Set tElement = ..REF2.GetAt(i)
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollREF2).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..REF2.%UnSwizzleAt(i)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	For i=1:1:..DTP1.Count() {
		Set tElement = ..DTP1.GetAt(i)
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollDTP).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..DTP1.%UnSwizzleAt(i)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(..NM1) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollNM1).PutObject(pIOStream,..NM1,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..PER) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollPER).PutObject(pIOStream,..PER,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..N3) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollN3).PutObject(pIOStream,..N3,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..N4) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollN4).PutObject(pIOStream,..N4,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..DMG) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollDMG).PutObject(pIOStream,..DMG,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..HD) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollHD).PutObject(pIOStream,..HD,0)
		If $$$ISERR(tStatus) Quit
	}
	For i=1:1:..DTP.Count() {
		Set tElement = ..DTP.GetAt(i)
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.DStruc.Record.SelectHealth.EnrollDTP2).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..DTP.%UnSwizzleAt(i)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus
